var useHelpCenterStore = defineStore("helpCenter", () => {
	const panels = useComfierPanelStore();
	const isVisible = computed(() => panels.isOpen("comfier-help"));
	const toggle = () => panels.toggle("comfier-help", "left");
	const show = () => panels.select("comfier-help", "left");
	const hide = () => panels.remove("comfier-help");
	return {
		isVisible,
		toggle,
		show,
		hide
	};
});
