//#region src/composables/useCanvasDrop.ts
var useCanvasDrop = (canvasRef) => {
	const modelToNodeStore = useModelToNodeStore();
	const litegraphService = useLitegraphService();
	const workflowService = useWorkflowService();
	usePragmaticDroppable(() => canvasRef.value, {
		getDropEffect: (args) => args.source.data.type === "tree-explorer-node" ? "copy" : "move",
		onDrop: async (event) => {
			if (isSelectOnly(app.canvas)) return;
			const loc = event.location.current.input;
			const dndData = event.source.data;
			if (dndData.type === "tree-explorer-node") {
				const node = dndData.data;
				const basePos = useSharedCanvasPositionConversion().clientPosToCanvasPos([loc.clientX, loc.clientY]);
				if (node.data instanceof ComfyNodeDefImpl) {
					const nodeDef = node.data;
					const pos = [...basePos];
					pos[1] += LiteGraph.NODE_TITLE_HEIGHT;
					withNodeAddSource("sidebar_drag", () => litegraphService.addNodeOnGraph(nodeDef, { pos }));
				} else if (node.data instanceof ComfyModelDef) {
					const model = node.data;
					const pos = basePos;
					const nodeAtPos = app.canvas.graph?.getNodeOnPos(pos[0], pos[1]);
					let targetProvider = null;
					let targetGraphNode = null;
					if (nodeAtPos) {
						const providers = modelToNodeStore.getAllNodeProviders(model.directory);
						for (const provider of providers) if (provider.nodeDef.name === nodeAtPos.comfyClass) {
							targetGraphNode = nodeAtPos;
							targetProvider = provider;
						}
					}
					if (!targetGraphNode) {
						const provider = modelToNodeStore.getNodeProvider(model.directory);
						if (provider) {
							targetGraphNode = withNodeAddSource("sidebar_drag", () => litegraphService.addNodeOnGraph(provider.nodeDef, { pos }));
							targetProvider = provider;
						}
					}
					if (targetGraphNode) {
						const widget = targetGraphNode.widgets?.find((widget) => widget.name === targetProvider?.key);
						if (widget) widget.value = model.file_name;
					}
				} else if (node.data instanceof ComfyWorkflow) {
					const workflow = node.data;
					await workflowService.insertWorkflow(workflow, { position: basePos });
				}
			}
		}
	});
};
//#endregion
//#region src/composables/useContextMenuTranslation.ts
function translateContextMenuItems(values, options) {
	if (!values) return;
	const reInput = /Convert (.*) to input/;
	const reWidget = /Convert (.*) to widget/;
	const cvt = st("contextMenu.Convert ", "Convert ");
	const tinp = st("contextMenu. to input", " to input");
	const twgt = st("contextMenu. to widget", " to widget");
	for (const value of values) {
		if (typeof value === "string") continue;
		translateContextMenuItems(value?.submenu?.options, options);
		if (!value?.content) continue;
		if (te(`contextMenu.${value.content}`)) value.content = st(`contextMenu.${value.content}`, value.content);
		const extraInfo = options.extra || options.parentMenu?.options.extra;
		const inputs = extraInfo?.inputs ?? [];
		const widgets = extraInfo?.widgets ?? [];
		const labelFor = (name) => inputs.find((input) => input.name === name)?.label ?? widgets.find((widget) => widget.name === name)?.label ?? name;
		const matchInput = value.content.match(reInput);
		if (matchInput) {
			value.content = cvt + labelFor(matchInput[1]) + tinp;
			continue;
		}
		const matchWidget = value.content.match(reWidget);
		if (matchWidget) value.content = cvt + labelFor(matchWidget[1]) + twgt;
	}
}
/**
* Add translation for litegraph context menu.
*/
var useContextMenuTranslation = () => {
	legacyMenuCompat.install(LGraphCanvas.prototype, "getCanvasMenuOptions");
	const { getCanvasMenuOptions } = LGraphCanvas.prototype;
	const getCanvasCenterMenuOptions = function(...args) {
		const res = getCanvasMenuOptions.apply(this, args);
		const newApiItems = app.collectCanvasMenuItems(this);
		for (const item of newApiItems) res.push(item);
		const legacyItems = legacyMenuCompat.extractLegacyItems("getCanvasMenuOptions", this, ...args);
		for (const item of legacyItems) res.push(item);
		for (const item of res) if (item?.content) item.content = st(`contextMenu.${item.content}`, item.content);
		return res;
	};
	LGraphCanvas.prototype.getCanvasMenuOptions = getCanvasCenterMenuOptions;
	legacyMenuCompat.registerWrapper("getCanvasMenuOptions", getCanvasCenterMenuOptions, getCanvasMenuOptions, LGraphCanvas.prototype);
	legacyMenuCompat.install(LGraphCanvas.prototype, "getNodeMenuOptions");
	const nodeMenuFn = LGraphCanvas.prototype.getNodeMenuOptions;
	const getNodeMenuOptionsWithExtensions = function(...args) {
		const res = nodeMenuFn.apply(this, args);
		const node = args[0];
		const newApiItems = app.collectNodeMenuItems(node);
		for (const item of newApiItems) res.push(item);
		const legacyItems = legacyMenuCompat.extractLegacyItems("getNodeMenuOptions", this, ...args);
		for (const item of legacyItems) res.push(item);
		return res;
	};
	LGraphCanvas.prototype.getNodeMenuOptions = getNodeMenuOptionsWithExtensions;
	legacyMenuCompat.registerWrapper("getNodeMenuOptions", getNodeMenuOptionsWithExtensions, nodeMenuFn, LGraphCanvas.prototype);
	const OriginalContextMenu = LiteGraph.ContextMenu;
	function ContextMenu(values, options) {
		if (options.title) options.title = resolveNodeDefText("display_name", options.title);
		translateContextMenuItems(values, options);
		return new OriginalContextMenu(values, options);
	}
	LiteGraph.ContextMenu = ContextMenu;
	LiteGraph.ContextMenu.prototype = OriginalContextMenu.prototype;
};
