//#region src/composables/useCopy.ts
var CANVAS_CLIPBOARD_KEY = "litegrapheditor_clipboard";
var CANVAS_CLIPBOARD_ID_KEY = "litegrapheditor_clipboard_id";
var clipboardHTMLWrapper = ["<meta charset=\"utf-8\"><div><span data-comfy-metadata=\"", "\"></span></div><span style=\"white-space:pre-wrap;\">Text</span>"];
var clipboardByteChunkSize = 32768;
function bytesToBinaryString(bytes) {
	const chunks = [];
	for (let offset = 0; offset < bytes.length; offset += clipboardByteChunkSize) chunks.push(String.fromCharCode(...bytes.subarray(offset, offset + clipboardByteChunkSize)));
	return chunks.join("");
}
function encodeClipboardData(data) {
	return btoa(bytesToBinaryString(new TextEncoder().encode(data)));
}
/**
* Adds a handler on copy that serializes selected nodes to JSON
*/
var useCopy = () => {
	const canvasStore = useCanvasStore();
	let keyboardCopyId = null;
	useEventListener(document, "copy", (e) => {
		if (shouldIgnoreCopyPaste(e.target)) {
			if (keyboardCopyId !== null && hasTextSelection(e.target) && localStorage.getItem(CANVAS_CLIPBOARD_ID_KEY) === keyboardCopyId) {
				localStorage.removeItem(CANVAS_CLIPBOARD_KEY);
				localStorage.removeItem(CANVAS_CLIPBOARD_ID_KEY);
				keyboardCopyId = null;
			}
			return;
		}
		const canvas = canvasStore.canvas;
		if (canvas?.selectedItems) {
			const serializedData = canvas.copyToClipboard();
			keyboardCopyId = localStorage.getItem(CANVAS_CLIPBOARD_ID_KEY);
			try {
				const base64Data = encodeClipboardData(serializedData);
				e.clipboardData?.setData("text/html", clipboardHTMLWrapper.join(base64Data));
			} catch (error) {
				console.error(error);
			}
			e.preventDefault();
			e.stopImmediatePropagation();
			return false;
		}
	});
};
