//#region src/platform/workflow/persistence/composables/useWorkflowTabState.ts
/**
* Gets the current client ID for browser tab identification.
* Falls back to initialClientId if clientId is not yet set.
*/
function getClientId() {
	return api.clientId ?? api.initialClientId ?? null;
}
/**
* Composable for managing per-tab workflow state in sessionStorage.
*/
function useWorkflowTabState() {
	/**
	* Gets the active workflow path for the current tab.
	* Returns null if no pointer exists or workspaceId doesn't match.
	*/
	function getActivePath() {
		const clientId = getClientId();
		const workspaceId = getWorkspaceId();
		if (!clientId) return null;
		return readActivePath(clientId, workspaceId)?.path ?? null;
	}
	/**
	* Sets the active workflow path for the current tab.
	*/
	function setActivePath(path) {
		const clientId = getClientId();
		const workspaceId = getWorkspaceId();
		if (!clientId) return;
		writeActivePath(clientId, {
			workspaceId,
			path
		});
	}
	/** Forgets the active workflow, so nothing is restored on the next boot. */
	function clearActivePathPointer() {
		const clientId = getClientId();
		if (!clientId) return;
		clearActivePath(clientId, getWorkspaceId());
	}
	/**
	* Gets the open workflow paths for the current tab.
	* Returns null if no pointer exists or workspaceId doesn't match.
	*/
	function getOpenPaths() {
		const clientId = getClientId();
		const workspaceId = getWorkspaceId();
		if (!clientId) return null;
		const pointer = readOpenPaths(clientId, workspaceId);
		if (!pointer) return null;
		return {
			paths: pointer.paths,
			activeIndex: pointer.activeIndex
		};
	}
	/**
	* Sets the open workflow paths for the current tab.
	*/
	function setOpenPaths(paths, activeIndex) {
		const clientId = getClientId();
		const workspaceId = getWorkspaceId();
		if (!clientId) return;
		writeOpenPaths(clientId, {
			workspaceId,
			paths,
			activeIndex
		});
	}
	return {
		getActivePath,
		setActivePath,
		clearActivePathPointer,
		getOpenPaths,
		setOpenPaths
	};
}
