var DIALOG_KEY = "global-model-selector";
var useModelSelectorDialog = () => {
	const dialogService = useDialogService();
	const dialogStore = useDialogStore();
	function hide() {
		dialogStore.closeDialog({ key: DIALOG_KEY });
	}
	function show() {
		dialogService.showLayoutDialog({
			key: DIALOG_KEY,
			component: SampleModelSelector_default,
			props: { onClose: hide }
		});
	}
	return {
		show,
		hide
	};
};
