//#region src/platform/onboarding/onboardingReset.ts
async function resetOnboardingState() {
	const ownerId = useAuthStore().userId;
	if (!requestOnboardingReplay(ownerId)) return {
		status: "failed",
		cause: "Session storage is unavailable, so the onboarding replay cannot be requested"
	};
	let response;
	try {
		response = await api.storeSetting(TOUR_SEEN_SETTING, []);
	} catch (cause) {
		clearOnboardingReplay(ownerId);
		return {
			status: "failed",
			cause
		};
	}
	if (!response.ok) {
		clearOnboardingReplay(ownerId);
		return {
			status: "failed",
			cause: `Failed to clear seen onboarding tours: ${response.status} ${response.statusText}`.trim()
		};
	}
	useSettingStore().settingValues[TOUR_SEEN_SETTING] = [];
	return { status: "ready" };
}
